,"label":"Próximo retorno","type":"date","required":false}],"statuses":["registrado"],"write":["admin","operacao"],"read":["admin","operacao","financeiro"],"help":""},"frase":{"label":"Vocabulário revisado","area":"assistente","fields":[{"name":"entrada","label":"Forma de falar","type":"textarea","required":true,"maxLength":4000},{"name":"comando","label":"Forma reconhecida/canônica","type":"textarea","required":true,"maxLength":4000},{"name":"motivo","label":"Correção revisada","type":"textarea","required":true,"maxLength":4000}],"statuses":["rascunho","aprovada","arquivada"],"write":["admin"],"read":["admin","operacao","financeiro","consulta"],"help":"Exemplos aprovados ampliam o vocabulário; conversa não altera regras sozinha."},"aviso":{"label":"Aviso e confirmação de leitura","area":"operacao","fields":[{"name":"cliente_id","label":"Cliente contratante","type":"ref","required":false,"target":"cliente"},{"name":"pedido_id","label":"Pedido","type":"ref","required":false,"target":"pedido"},{"name":"perfil","label":"Destinatários","type":"choice","required":true,"options":["todos","operacao","financeiro","consulta"]},{"name":"email","label":"Destinatário específico","type":"email","required":false},{"name":"mensagem","label":"Mensagem","type":"textarea","required":true,"maxLength":4000},{"name":"validade","label":"Validade","type":"date","required":false}],"statuses":["publicado","arquivado"],"write":["admin"],"read":["admin","operacao","financeiro","consulta"],"help":""},"leitura_aviso":{"label":"Leitura de aviso","area":"operacao","fields":[{"name":"aviso_id","label":"Aviso","type":"ref","required":true,"target":"aviso"}],"statuses":["lido"],"write":["admin","operacao","financeiro","consulta"],"read":["admin","operacao","financeiro","consulta"],"help":"","unique":["aviso_id","autor"]},"acesso":{"label":"Escopo do funcionário","area":"configuracoes","fields":[{"name":"email","label":"E-mail do funcionário","type":"email","required":true},{"name":"cliente_id","label":"Cliente permitido","type":"ref","required":true,"target":"cliente"},{"name":"observacoes","label":"Observações","type":"textarea","required":false,"maxLength":4000}],"statuses":["ativo","arquivado"],"write":["admin"],"read":["admin"],"help":"Quando houver escopos ativos, os novos módulos ficam restritos aos clientes permitidos. Não amplia o perfil existente."},"regra":{"label":"Regra de acompanhamento","area":"configuracoes","fields":[{"name":"tipo","label":"Acompanhar","type":"choice","required":true,"options":["tarefa_vencida","qualificacao_vencida","lote_vencido","cobranca_atrasada"]},{"name":"antecedencia_dias","label":"Antecedência, em dias","type":"integer","required":true,"min":0,"max":1000000},{"name":"responsavel","label":"Responsável","type":"text","required":true},{"name":"acao","label":"Ação sugerida","type":"textarea","required":true,"maxLength":4000}],"statuses":["ativo","arquivado"],"write":["admin"],"read":["admin","operacao","financeiro","consulta"],"help":"Gera alertas internos com base nos registros; não envia WhatsApp automaticamente."}}}$json$::jsonb$contract$;
-- Additive business workspace. Existing records and identifiers are preserved.
create table public.empresa_registros (
 id bigint generated by default as identity primary key,tipo text not null,titulo text not null check(length(trim(titulo)) between 1 and 180),
 status text not null,dados jsonb not null check(jsonb_typeof(dados)='object'),
 cliente_id bigint references public.empresa_registros(id),campanha_id bigint references public.empresa_registros(id),
 pedido_id bigint references public.pedidos(id),diarista_id bigint references public.diaristas(id),loja_id bigint references public.lojas(id),
 chave text not null unique check(length(chave) between 8 and 180),versao bigint not null default 1,
 autor text not null,criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now()
);
create index empresa_tipo_cliente on public.empresa_registros(tipo,cliente_id,id desc);
create index empresa_pedido on public.empresa_registros(pedido_id,tipo);
create index empresa_campanha on public.empresa_registros(campanha_id,tipo);
create index empresa_diarista on public.empresa_registros(diarista_id,tipo);
create index empresa_loja on public.empresa_registros(loja_id,tipo);
create unique index empresa_vinculo_unico on public.empresa_registros(pedido_id) where tipo='vinculo';
create unique index empresa_ciencia_unica on public.empresa_registros((dados->>'briefing_id'),diarista_id) where tipo='ciencia';
create unique index empresa_leitura_unica on public.empresa_registros((dados->>'aviso_id'),autor) where tipo='leitura_aviso';
create unique index empresa_fechamento_unico on public.empresa_registros((dados->>'data'),coalesce(pedido_id,0),coalesce(cliente_id,0),coalesce(campanha_id,0)) where tipo='fechamento';
create table public.empresa_extrato (
 id bigint generated by default as identity primary key,conta_id bigint not null references public.empresa_registros(id),
 chave text not null unique,data date not null,valor_centavos bigint not null check(valor_centavos<>0 and abs(valor_centavos)<=1000000000),
 descricao text not null,identificador text not null default '',estado text not null default 'pendente' check(estado in ('pendente','conciliado','ignorada')),
 destino_tipo text,destino_id bigint,motivo text not null default '',versao bigint not null default 1,
 criado_em timestamptz not null default now(),atualizado_em timestamptz not null default now()
);
create index empresa_extrato_conta_data on public.empresa_extrato(conta_id,data desc,id desc);
create unique index empresa_extrato_baixa on public.empresa_extrato(destino_tipo,destino_id) where estado='conciliado' and destino_tipo in ('lancamento','lote_pagamento');
create table public.empresa_anexos (
 id bigint generated by default as identity primary key,registro_id bigint not null references public.empresa_registros(id),
 nome text not null,mime text not null check(mime in ('image/jpeg','image/png','image/webp')),
 bytes bigint not null check(bytes between 1 and 1048576),caminho text not null unique,
 sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),criado_em timestamptz not null default now(),autor text not null
);
create index empresa_anexos_registro on public.empresa_anexos(registro_id);
create table direct_private.empresa_compartilhamentos (
 id bigint generated by default as identity primary key,registro_id bigint not null unique references public.empresa_registros(id),
 codigo text not null unique default translate(encode(extensions.gen_random_bytes(18),'base64'),'+/','-_'),criado_em timestamptz not null default now()
);
alter table direct_private.empresa_compartilhamentos enable row level security;
revoke all on direct_private.empresa_compartilhamentos from public,anon,authenticated;
alter table public.financeiro_lancamentos add column empresa_registro_id bigint references public.empresa_registros(id);
create unique index financeiro_empresa_unico on public.financeiro_lancamentos(empresa_registro_id) where empresa_registro_id is not null;

create function direct_private.empresa_role() returns text language plpgsql stable security definer set search_path='' as $$
declare r text:=direct_private.member_role();begin
 if auth.uid() is null or coalesce(r,'') not in ('admin','operacao','financeiro','consulta') then raise exception 'Entre com um perfil autorizado.' using errcode='42501';end if;return r;
end;$$;
create function direct_private.empresa_scope(cid bigint) returns boolean language sql stable security definer set search_path='' as $$
 select direct_private.member_role()='admin' or not exists(select 1 from public.empresa_registros where tipo='acesso' and status='ativo' and lower(dados->>'email')=lower(auth.jwt()->>'email')) or exists(select 1 from public.empresa_registros where tipo='acesso' and status='ativo' and lower(dados->>'email')=lower(auth.jwt()->>'email') and cliente_id=cid)
$$;
create function direct_private.empresa_visible(r public.empresa_registros) returns boolean language plpgsql stable security definer set search_path='' as $$
declare member text:=direct_private.member_role();spec jsonb:=direct_private.empresa_contract()->'entities'->r.tipo;
begin
 if auth.uid() is null or not coalesce(spec->'read' ? member,false) then return false;end if;
 if r.tipo='leitura_aviso' and member<>'admin' then return r.autor=auth.jwt()->>'email';end if;
 if r.tipo='aviso' and member<>'admin' and ((r.dados->>'perfil' not in ('todos',member)) or (coalesce(r.dados->>'email','')<>'' and lower(r.dados->>'email')<>lower(auth.jwt()->>'email'))) then return false;end if;
 if r.tipo in ('categoria','material','lote','movimento','conta','rede','checklist_modelo','qualificacao','frase','regra','leitura_aviso','acesso') and r.cliente_id is null then return true;end if;
 return direct_private.empresa_scope(case when r.tipo='cliente' then r.id else r.cliente_id end);
end;$$;
do $$declare t text;begin foreach t in array array['empresa_registros','empresa_extrato','empresa_anexos'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from public,anon,authenticated',t);
 execute format('grant select on public.%I to authenticated',t);
 execute format('create trigger audit_empresa after insert or update or delete on public.%I for each row execute function direct_private.log_change()',t);
 execute format('create trigger empresa_revision after insert or update or delete on public.%I for each statement execute function direct_private.bump_revision()',t);
end loop;end;$$;
create policy empresa_read on public.empresa_registros for select to authenticated using(direct_private.empresa_visible(empresa_registros));
create policy empresa_bank_read on public.empresa_extrato for select to authenticated using((select direct_private.member_role()) in ('admin','financeiro'));
create policy empresa_attachment_read on public.empresa_anexos for select to authenticated using(exists(select 1 from public.empresa_registros r where r.id=registro_id));

create function direct_private.empresa_get(rid bigint,kind text default null) returns public.empresa_registros language plpgsql stable security definer set search_path='' as $$
declare r public.empresa_registros;begin select * into r from public.empresa_registros where id=rid;
 if r.id is null or (kind is not null and r.tipo<>kind) or not direct_private.empresa_visible(r) then raise exception 'Registro não disponível para seu perfil.' using errcode='42501';end if;return r;
end;$$;
create function direct_private.empresa_stock(rid bigint) returns bigint language plpgsql stable security definer set search_path='' as $$
declare r public.empresa_registros:=direct_private.empresa_get(rid,'material');begin
 return (r.dados->>'quantidade_inicial')::bigint+coalesce((select sum((dados->>'quantidade')::bigint*case when dados->>'tipo' in ('entrada','devolucao') then 1 else -1 end) from public.empresa_registros where tipo='movimento' and (dados->>'material_id')::bigint=rid),0);
end;$$;
create function direct_private.empresa_form_data(kind text,d jsonb) returns jsonb language sql immutable set search_path='' as $$select coalesce(jsonb_object_agg(k,v),'{}') from jsonb_each(d) x(k,v) where exists(select 1 from jsonb_array_elements(direct_private.empresa_contract()->'entities'->kind->'fields') a where a->>'name'=k)$$;
create function direct_private.empresa_validate(kind text,raw jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare spec jsonb:=direct_private.empresa_contract()->'entities'->kind;f jsonb;n text;t text;v jsonb;d jsonb:='{}';ref public.empresa_registros;target text;native boolean;test boolean;value text;
begin
 if spec is null or jsonb_typeof(raw)<>'object' then raise exception 'Formulário inválido.';end if;
 if exists(select 1 from jsonb_object_keys(raw) k where not exists(select 1 from jsonb_array_elements(spec->'fields') x where x->>'name'=k)) then raise exception 'Campos não reconhecidos.';end if;
 for f in select * from jsonb_array_elements(spec->'fields') loop
  n:=f->>'name';t:=f->>'type';v:=raw->n;value:=trim(raw->>n);
  if v is null or v='null'::jsonb or value='' or v='[]'::jsonb then if (f->>'required')::boolean then raise exception 'Preencha %.',f->>'label';end if;continue;end if;
  if t in ('integer','money','ref') then
   if jsonb_typeof(v)<>'number' or value !~ '^[0-9]+$' or value::numeric<coalesce((f->>'min')::numeric,1) or value::numeric>coalesce((f->>'max')::numeric,9007199254740991) then raise exception 'Valor inválido: %.',f->>'label';end if;
  elsif t in ('lines','ids','answers') then
   if jsonb_typeof(v)<>'array' or jsonb_array_length(v)>100 then raise exception 'Lista inválida: %.',f->>'label';end if;
   if t='lines' and exists(select 1 from jsonb_array_elements(v) x where jsonb_typeof(x)<>'string' or length(trim(x#>>'{}')) not between 1 and 500) then raise exception 'Perguntas inválidas.';end if;
   if t='ids' and (exists(select 1 from jsonb_array_elements(v) x where jsonb_typeof(x)<>'number' or (x#>>'{}') !~ '^[1-9][0-9]*$') or (select count(distinct x) from jsonb_array_elements(v)x)<>jsonb_array_length(v)) then raise exception 'IDs de diárias inválidos.';end if;
   if t='answers' and exists(select 1 from jsonb_array_elements(v) x where jsonb_typeof(x)<>'object' or jsonb_typeof(x->'pergunta')<>'string' or jsonb_typeof(x->'resposta')<>'string' or length(x->>'pergunta')>500 or length(x->>'resposta')>2000 or exists(select 1 from jsonb_object_keys(x) k where k not in ('pergunta','resposta'))) then raise exception 'Respostas inválidas.';end if;
  else
   if jsonb_typeof(v)<>'string' or length(value)>coalesce((f->>'maxLength')::int,case when t='textarea' then 4000 else 180 end) then raise exception 'Texto inválido: %.',f->>'label';end if;
   if t='choice' and not (f->'options' ? value) then raise exception 'Opção inválida: %.',f->>'label';end if;
   if t='date' then if value !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Data inválida.';end if;perform value::date;end if;
   if t='datetime' then if value !~ '(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'Informe o fuso horário.';end if;perform value::timestamptz;end if;
   if t='time' and value !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' then raise exception 'Horário inválido.';end if;
   if t='email' and value !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'E-mail inválido.';end if;
   v:=to_jsonb(value);
  end if;
  if t='ref' then
   target:=f->>'target';native:=target in ('pedido','diarista','loja','cobranca');
   if native then
    if target='pedido' then select exists(select 1 from public.pedidos where id=value::bigint) into test;
    elsif target='diarista' then select exists(select 1 from public.diaristas where id=value::bigint) into test;
    elsif target='cobranca' then if direct_private.empresa_role() not in ('admin','financeiro') then raise exception 'Sem permissão para cobranças.' using errcode='42501';end if;select exists(select 1 from public.cobrancas where id=value::bigint) into test;
    else select exists(select 1 from public.lojas where id=value::bigint) into test;end if;
    if not test then raise exception 'Vínculo não encontrado: %.',f->>'label';end if;
   else ref:=direct_private.empresa_get(value::bigint,target);end if;
  end if;
  d:=d||jsonb_build_object(n,v);
 end loop;
 if d ? 'inicio' and d ? 'fim' and d->>'inicio'>d->>'fim' then raise exception 'Confira início e fim.';end if;
 if d ? 'campanha_id' then ref:=direct_private.empresa_get((d->>'campanha_id')::bigint,'campanha');if d ? 'cliente_id' and d->>'cliente_id'<>ref.dados->>'cliente_id' then raise exception 'O cliente deve ser o contratante da campanha.';end if;d:=d||jsonb_build_object('cliente_id',ref.cliente_id);end if;
 return d;
end;$$;

create function direct_private.empresa_closing(d jsonb) returns jsonb language sql stable security definer set search_path='' as $$
 with scope as(select p.id from public.pedidos p where p.situacao<>'cancelado' and (not d ? 'pedido_id' or p.id=(d->>'pedido_id')::bigint) and (not d ? 'campanha_id' or exists(select 1 from public.empresa_registros v where v.tipo='vinculo' and v.pedido_id=p.id and v.campanha_id=(d->>'campanha_id')::bigint)) and (not d ? 'cliente_id' or exists(select 1 from public.empresa_registros v where v.tipo='vinculo' and v.pedido_id=p.id and v.cliente_id=(d->>'cliente_id')::bigint)))
 select jsonb_build_object('vagas_pendentes',(select coalesce(sum(greatest(0,(select count(*)*o.quantidade_diaristas from jsonb_array_elements(o.turnos) t where t->>'data'=d->>'data')-(select count(*) from public.pedido_escalas s where s.pedido_id=o.id and s.data=(d->>'data')::date and s.status not in ('falta','desistiu')))),0) from public.pedidos o join scope p on p.id=o.id),'presencas_pendentes',(select count(*) from public.pedido_escalas s join scope p on p.id=s.pedido_id where s.data=(d->>'data')::date and s.status='escalada'),
 'valores_incompletos',(select count(*) from public.diarias t join public.pedido_escalas s on s.id=t.pedido_escala_id join scope p on p.id=s.pedido_id where t.data=(d->>'data')::date and (t.valor_centavos is null or t.valor_recebido_centavos is null)),
 'ocorrencias_abertas',(select count(*) from public.ocorrencias o join scope p on p.id=o.pedido_id where o.estado='aberta'),
 'conferencias_loja',(select count(*) from public.loja_validacoes v join public.pedido_escalas s on s.id=v.escala_id join scope p on p.id=s.pedido_id where s.data=(d->>'data')::date and v.estado='pendente'))
$$;

create function public.direct_empresa_registro(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();kind text:=p->>'tipo';spec jsonb:=direct_private.empresa_contract()->'entities'->kind;
 rid bigint:=nullif(p->>'id','')::bigint;r public.empresa_registros;old public.empresa_registros;d jsonb;state text;f jsonb;filtered jsonb;q jsonb;item jsonb;required boolean;applicable boolean;condition text[];balance bigint;held bigint;category public.empresa_registros;total bigint;cnt bigint;snapshot jsonb;
begin
 if kind is null then return to_jsonb(direct_private.empresa_get(rid));end if;
 if not coalesce(spec->'write' ? member,false) then raise exception 'Seu perfil não pode alterar esta informação.' using errcode='42501';end if;
 state:=coalesce(p->>'status',spec->'statuses'->>0);if not spec->'statuses' ? state then raise exception 'Situação inválida.';end if;
 if length(trim(coalesce(p->>'titulo',''))) not between 1 and 180 then raise exception 'Informe um título.';end if;
 if rid is not null then old:=direct_private.empresa_get(rid,kind);select * into old from public.empresa_registros where id=rid for update;if old.versao<>coalesce((p->>'versao')::bigint,0) then raise exception 'Outra pessoa alterou o registro. Atualize antes de salvar.';end if;
 else
  if coalesce(p->>'chave','') !~ '^[A-Za-z0-9:_-]{8,180}$' then raise exception 'Chave de envio inválida.';end if;
  perform pg_advisory_xact_lock(hashtextextended(p->>'chave',0));
  select * into r from public.empresa_registros where chave=p->>'chave';
 end if;
 d:=direct_private.empresa_validate(kind,coalesce(p->'dados','{}'));
 if not direct_private.empresa_scope((d->>'cliente_id')::bigint) and kind not in ('material','lote','movimento','categoria','conta','rede','checklist_modelo','qualificacao','frase','regra','leitura_aviso') then raise exception 'Cliente fora do seu escopo.' using errcode='42501';end if;
 if r.id is not null then filtered:=(select coalesce(jsonb_object_agg(k,v),'{}') from jsonb_each(r.dados) x(k,v) where exists(select 1 from jsonb_array_elements(spec->'fields') a where a->>'name'=k));if r.tipo<>kind or r.titulo<>trim(p->>'titulo') or r.status<>state or filtered<>direct_private.empresa_form_data(kind,d) then raise exception 'Envio já registrado com outros dados.';end if;return to_jsonb(direct_private.empresa_get(r.id));end if;
 if old.id is not null and ((kind='proposta' and old.status in ('enviada','aprovada','perdida','convertida')) or (kind='briefing' and old.status='publicado') or (kind='relatorio' and old.status='aprovado') or (kind='checklist' and old.status='concluido') or (kind='fechamento' and old.status='fechado') or kind in ('movimento','movimento_caixa','ciencia','leitura_aviso') or kind='orcamento' and old.status='aprovado' or kind='pagamento_revisao' and old.status='registrado') then
  filtered:=(select coalesce(jsonb_object_agg(k,v),'{}') from jsonb_each(old.dados) x(k,v) where exists(select 1 from jsonb_array_elements(spec->'fields') a where a->>'name'=k));
  if filtered<>direct_private.empresa_form_data(kind,d) or (state<>old.status and not(kind='proposta' and old.status='enviada' and state in ('aprovada','perdida'))) or old.titulo<>trim(p->>'titulo') then raise exception 'Esta versão está preservada. Crie uma nova versão.';end if;
 end if;
 if kind='movimento_caixa' and (d->>'valor_centavos')::bigint<=0 then raise exception 'Informe valor maior que zero.';end if;
 if kind='feedback' and (d->>'nota')::int not between 1 and 5 then raise exception 'A nota deve ficar entre 1 e 5.';end if;
 if kind='tarefa' and state='concluida' and length(coalesce(d->>'resolucao',''))<5 then raise exception 'Registre a resolução da tarefa.';end if;
 if kind='visita' and state='realizada' and coalesce(d->>'resultado','')='' then raise exception 'Registre o resultado da visita.';end if;
 if kind='fechamento' and state='fechado' then
  if (d->>'data')::date>(now() at time zone 'America/Fortaleza')::date then raise exception 'Feche somente um dia já iniciado.';end if;q:=direct_private.empresa_closing(d);d:=d||jsonb_build_object('pendencias',q);
  if exists(select 1 from jsonb_each_text(q) where value::bigint>0) and length(coalesce(d->>'justificativa',''))<8 then raise exception 'Resolva ou justifique as pendências antes de fechar.';end if;
 end if;
 if kind='ciencia' then r:=direct_private.empresa_get((d->>'briefing_id')::bigint,'briefing');if r.status<>'publicado' then raise exception 'Confirme uma versão publicada.';end if;end if;
 if kind='checklist' then
  r:=direct_private.empresa_get((d->>'modelo_id')::bigint,'checklist_modelo');
  if exists(select 1 from jsonb_array_elements(d->'respostas') a where not(r.dados->'perguntas' ? (a->>'pergunta'))) or (select count(distinct a->>'pergunta') from jsonb_array_elements(d->'respostas') a)<>jsonb_array_length(d->'respostas') then raise exception 'Respostas não correspondem ao modelo.';end if;
  if state='concluido' then for q in select * from jsonb_array_elements(r.dados->'perguntas') loop
   condition:=regexp_match(q#>>'{}','\[se (.+?)=(.+?)\]');applicable:=condition is null or exists(select 1 from jsonb_array_elements(d->'respostas') a where a->>'pergunta'=trim(condition[1]) and lower(trim(a->>'resposta'))=lower(trim(condition[2])));
   if left(q#>>'{}',1)='*' and applicable and not exists(select 1 from jsonb_array_elements(d->'respostas') a where a->>'pergunta'=q#>>'{}' and length(trim(a->>'resposta'))>0) then raise exception 'Responda as perguntas obrigatórias aplicáveis.';end if;
  end loop;end if;d:=d||jsonb_build_object('perguntas_snapshot',r.dados->'perguntas');
 end if;
 if kind='amostra' then balance:=(d->>'saldo_inicial')::bigint+(d->>'recebidas')::bigint-(d->>'distribuidas')::bigint-(d->>'perdas')::bigint-(d->>'devolvidas')::bigint;if balance<0 then raise exception 'Unidades distribuídas excedem o disponível.';end if;if coalesce((d->>'vendas')::bigint,0)>0 and coalesce(d->>'fonte_vendas','')='' then raise exception 'Informe a fonte das vendas observadas.';end if;d:=d||jsonb_build_object('saldo_final',balance);end if;
 if kind='movimento' and old.id is null then
  perform 1 from public.empresa_registros where id=(d->>'material_id')::bigint for update;
  if (d->>'quantidade')::bigint<=0 then raise exception 'Informe uma quantidade maior que zero.';end if;
  if d->>'tipo' not in ('entrada','devolucao') and (d->>'quantidade')::bigint>direct_private.empresa_stock((d->>'material_id')::bigint) then raise exception 'Saldo insuficiente do material.';end if;
  if d ? 'lote_id' then r:=direct_private.empresa_get((d->>'lote_id')::bigint,'lote');if r.dados->>'material_id'<>d->>'material_id' or (d->>'tipo' in ('entrega','consumo') and (r.dados->>'validade')::date<(d->>'data')::date) then raise exception 'Confira o material e a validade do lote.';end if;end if;
  if d->>'tipo'='devolucao' then select coalesce(sum((dados->>'quantidade')::bigint*case when dados->>'tipo'='entrega' then 1 when dados->>'tipo'='devolucao' then -1 else 0 end),0) into held from public.empresa_registros where tipo='movimento' and dados->>'material_id'=d->>'material_id' and dados->>'diarista_id' is not distinct from d->>'diarista_id' and dados->>'campanha_id' is not distinct from d->>'campanha_id';if (d->>'quantidade')::bigint>held then raise exception 'Devolução excede o material entregue.';end if;end if;
 end if;
 if kind='material' and old.id is not null and old.dados->>'quantidade_inicial'<>d->>'quantidade_inicial' and exists(select 1 from public.empresa_registros where tipo='movimento' and dados->>'material_id'=old.id::text) then raise exception 'Registre uma movimentação para corrigir o saldo.';end if;
 if kind='despesa' then
  category:=direct_private.empresa_get((d->>'categoria_id')::bigint,'categoria');if category.dados->>'tipo'<>'despesa' or (d->>'valor_centavos')::bigint<=0 then raise exception 'Confira categoria e valor da despesa.';end if;
  if state in ('aprovada','recusada','paga') and member not in ('admin','financeiro') then raise exception 'Somente Financeiro/Admin pode aprovar ou pagar despesas.' using errcode='42501';end if;
  if old.id is null and state not in ('rascunho','enviada') then raise exception 'Envie a despesa antes de aprovar.';end if;
  if old.id is not null then
   if not(case old.status when 'rascunho' then state in ('rascunho','enviada') when 'enviada' then state in ('enviada','aprovada','recusada') when 'recusada' then state in ('recusada','rascunho','enviada') when 'aprovada' then state in ('aprovada','paga') else state='paga' end) then raise exception 'Transição de despesa inválida.';end if;
   if old.status in ('aprovada','paga') and (old.titulo<>trim(p->>'titulo') or exists(select 1 from unnest(array['valor_centavos','categoria_id','data','vencimento','contraparte','pedido_id','cliente_id','campanha_id']) k where old.dados->k is distinct from d->k)) then raise exception 'Preserve a despesa aprovada; faça um ajuste financeiro separado.';end if;
  end if;
  if state='recusada' and length(coalesce(d->>'motivo',''))<5 then raise exception 'Explique a recusa.';end if;
  if state='paga' and (not d ? 'data_pagamento' or not d ? 'forma') then raise exception 'Informe data e forma de pagamento.';end if;
 end if;
 if kind='pagamento_revisao' then
  if state='registrado' then raise exception 'Use Registrar pagamento para concluir a conferência aprovada.';end if;
  select count(*),sum(valor_centavos),jsonb_agg(jsonb_build_object('id',id,'diarista_id',diarista_id,'valor_centavos',valor_centavos,'data_pagamento',data_pagamento) order by id) into cnt,total,snapshot from public.diarias where id in(select value::text::bigint from jsonb_array_elements(d->'diaria_ids')) and diarista_id=(d->>'diarista_id')::bigint and valor_centavos is not null and data_pagamento is null;
  if cnt<>jsonb_array_length(d->'diaria_ids') then raise exception 'Confira beneficiário, valores e diárias pendentes.';end if;
  if state='aprovado' and (old.id is null or old.status<>'preparado' or old.dados->'diarias_snapshot'<>snapshot) then raise exception 'Prepare novamente: as diárias mudaram ou não foram conferidas.';end if;
  d:=d||jsonb_build_object('valor_conferido_centavos',total,'diarias_snapshot',snapshot);
 end if;
 if kind='proposta' then
  if (d->>'dias')::int not between 1 and 90 or (d->>'pessoas')::int not between 1 and 100 or d->>'hora_inicio'>=d->>'hora_fim' then raise exception 'Confira dias, pessoas e horário.';end if;
  if old.id is null and state<>'rascunho' or state='convertida' then raise exception 'Prepare a proposta; use Gerar pedido para converter.';end if;
  d:=d||jsonb_build_object('receita_prevista_centavos',(d->>'dias')::bigint*(d->>'pessoas')::bigint*(d->>'valor_unitario_centavos')::bigint,'custo_previsto_centavos',(d->>'dias')::bigint*(d->>'pessoas')::bigint*(d->>'custo_unitario_centavos')::bigint+(d->>'extras_centavos')::bigint);
 end if;
 if kind='relatorio' and state='aprovado' and length(coalesce(d->>'aprovado_por',''))=0 then raise exception 'Registre quem revisou o relatório.';end if;
 if kind='leitura_aviso' then r:=direct_private.empresa_get((d->>'aviso_id')::bigint,'aviso');d:=d||jsonb_build_object('autor',auth.jwt()->>'email');select * into r from public.empresa_registros where tipo='leitura_aviso' and dados->>'aviso_id'=d->>'aviso_id' and autor=auth.jwt()->>'email' for update;if old.id is null and r.id is not null then return to_jsonb(r);end if;end if;
 if kind='acesso' and not exists(select 1 from public.direct_staff where lower(email)=lower(d->>'email') and active) then raise exception 'Escolha um funcionário ativo.';end if;
 if old.id is null then
  insert into public.empresa_registros(tipo,titulo,status,dados,cliente_id,campanha_id,pedido_id,diarista_id,loja_id,chave,autor) values(kind,trim(p->>'titulo'),state,d,(d->>'cliente_id')::bigint,(d->>'campanha_id')::bigint,(d->>'pedido_id')::bigint,(d->>'diarista_id')::bigint,(d->>'loja_id')::bigint,p->>'chave',auth.jwt()->>'email') returning * into r;
 else update public.empresa_registros set titulo=trim(p->>'titulo'),status=state,dados=d,cliente_id=(d->>'cliente_id')::bigint,campanha_id=(d->>'campanha_id')::bigint,pedido_id=(d->>'pedido_id')::bigint,diarista_id=(d->>'diarista_id')::bigint,loja_id=(d->>'loja_id')::bigint,versao=versao+1,atualizado_em=clock_timestamp() where id=old.id returning * into r;end if;
 if kind='despesa' and state in ('aprovada','paga') then
  insert into public.financeiro_lancamentos(tipo,descricao,categoria,contraparte,valor_centavos,vencimento,data_pagamento,forma_pagamento,observacoes,empresa_registro_id) values('despesa',r.titulo,category.titulo,d->>'contraparte',(d->>'valor_centavos')::bigint,(d->>'vencimento')::date,(d->>'data_pagamento')::date,coalesce(d->>'forma',''),d->>'justificativa',r.id) on conflict(empresa_registro_id) where empresa_registro_id is not null do nothing;
  if state='paga' then update public.financeiro_lancamentos set data_pagamento=(d->>'data_pagamento')::date,forma_pagamento=d->>'forma',atualizado_em=clock_timestamp() where empresa_registro_id=r.id;end if;
 end if;
 select * into r from public.empresa_registros where id=r.id;return to_jsonb(r);
end;$$;

create function public.direct_empresa_lista(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();kind text:=p->>'tipo';page int:=greatest(1,coalesce((p->>'pagina')::int,1));size int:=least(50,greatest(1,coalesce((p->>'tamanho')::int,25)));total bigint;items jsonb;
begin
 if not coalesce(direct_private.empresa_contract()->'entities'->kind->'read' ? member,false) then raise exception 'Seu perfil não pode consultar esta área.' using errcode='42501';end if;
 with filtered as(select r.* from public.empresa_registros r where r.tipo=kind and direct_private.empresa_visible(r) and (coalesce(p->>'busca','')='' or r.titulo ilike '%'||(p->>'busca')||'%' or r.dados::text ilike '%'||(p->>'busca')||'%') and (coalesce(p->>'status','')='' or r.status=p->>'status') and (coalesce(p->>'cliente_id','')='' or r.cliente_id=(p->>'cliente_id')::bigint) and (coalesce(p->>'campanha_id','')='' or r.campanha_id=(p->>'campanha_id')::bigint) and (coalesce(p->>'pedido_id','')='' or r.pedido_id=(p->>'pedido_id')::bigint))
 select (select count(*) from filtered),(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select * from filtered order by id desc limit size offset (page-1)*size)x) into total,items;
 return jsonb_build_object('items',items,'total',total,'pagina',page,'tamanho',size);
end;$$;
create function public.direct_empresa_opcoes(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();kind text:=p->>'tipo';search text:=coalesce(p->>'busca','');rid bigint:=nullif(p->>'id','')::bigint;result jsonb;
begin
 if kind='pedido' then select coalesce(jsonb_agg(to_jsonb(x)),'[]') into result from(select id,'Pedido #'||id||' · '||supermercado||' · '||unidade titulo from public.pedidos where (rid is null or id=rid) and (id::text||' '||supermercado||' '||unidade) ilike '%'||search||'%' order by id desc limit 100)x;
 elsif kind='diarista' then select coalesce(jsonb_agg(to_jsonb(x)),'[]') into result from(select id,nome titulo from public.diaristas where (rid is null or id=rid) and (nome||' '||cpf) ilike '%'||search||'%' order by id desc limit 100)x;
 elsif kind='cobranca' then if member not in ('admin','financeiro') then raise exception 'Sem permissão para cobranças.' using errcode='42501';end if;select coalesce(jsonb_agg(to_jsonb(x)),'[]') into result from(select id,'Cobrança #'||id||' · '||rede titulo from public.cobrancas where (rid is null or id=rid) and (id::text||' '||rede) ilike '%'||search||'%' order by id desc limit 100)x;
 elsif kind='loja' then select coalesce(jsonb_agg(to_jsonb(x)),'[]') into result from(select id,rede||' · '||nome titulo from public.lojas where (rid is null or id=rid) and (rede||' '||nome) ilike '%'||search||'%' order by id desc limit 100)x;
 else
  if not coalesce(direct_private.empresa_contract()->'entities'->kind->'read' ? member,false) then raise exception 'Tipo de busca não permitido.' using errcode='42501';end if;
  select coalesce(jsonb_agg(to_jsonb(x)),'[]') into result from(select id,titulo,status from public.empresa_registros r where tipo=kind and direct_private.empresa_visible(r) and (rid is null or id=rid) and (rid is not null or status not in ('arquivado','cancelada')) and titulo ilike '%'||search||'%' order by titulo limit 100)x;
 end if;return result;
end;$$;
create function public.direct_empresa_saldo(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$begin perform direct_private.empresa_role();return jsonb_build_object('saldo',direct_private.empresa_stock((p->>'material_id')::bigint));end;$$;

create function public.direct_empresa_converter_proposta(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();r public.empresa_registros;d jsonb;s public.lojas;oid bigint;shifts jsonb;
begin
 if member not in ('admin','financeiro') then raise exception 'Somente Financeiro/Admin converte propostas.' using errcode='42501';end if;
 r:=direct_private.empresa_get((p->>'id')::bigint,'proposta');select * into r from public.empresa_registros where id=r.id for update;d:=r.dados;
 if r.status='convertida' then return jsonb_build_object('pedido_id',(d->>'pedido_convertido_id')::bigint,'repetido',true);end if;
 if r.status<>'aprovada' or r.versao<>coalesce((p->>'versao')::bigint,0) then raise exception 'Atualize e escolha uma proposta aprovada.';end if;
 if (d->>'valor_unitario_centavos')::bigint<=0 or (d->>'custo_unitario_centavos')::bigint<=0 then raise exception 'Confira os valores contratados.';end if;
 select * into s from public.lojas where id=r.loja_id;
 select jsonb_agg(jsonb_build_object('data',(d->>'inicio')::date+i,'inicio',d->>'hora_inicio','fim',d->>'hora_fim') order by i) into shifts from generate_series(0,(d->>'dias')::int-1) i;
 insert into public.pedidos(supermercado,unidade,setor,quantidade_diaristas,turnos,situacao,observacoes) values(s.rede,s.nome,d->>'setor',(d->>'pessoas')::int,shifts,'novo',left('Proposta #'||r.id||' · '||(d->>'condicoes'),500)) returning id into oid;
 update public.empresa_registros set status='convertida',pedido_id=oid,dados=d||jsonb_build_object('pedido_convertido_id',oid),versao=versao+1,atualizado_em=clock_timestamp() where id=r.id;
 if r.campanha_id is not null then insert into public.empresa_registros(tipo,titulo,status,dados,pedido_id,campanha_id,cliente_id,chave,autor) values('vinculo','Pedido #'||oid,'ativo',jsonb_build_object('pedido_id',oid,'campanha_id',r.campanha_id,'cliente_id',r.cliente_id),oid,r.campanha_id,r.cliente_id,'proposta:vinculo:'||r.id,auth.jwt()->>'email');end if;
 return jsonb_build_object('pedido_id',oid,'proposta_id',r.id);
end;$$;
create function direct_private.empresa_quote_snapshot() returns trigger language plpgsql security definer set search_path='' as $$
declare d jsonb;begin
 if new.pedido_escala_id is null then return new;end if;
 select r.dados into d from public.empresa_registros r join public.pedido_escalas s on s.pedido_id=r.pedido_id where r.tipo='proposta' and r.status='convertida' and s.id=new.pedido_escala_id;
 if d is not null then new.valor_centavos:=(d->>'custo_unitario_centavos')::bigint;new.valor_recebido_centavos:=(d->>'valor_unitario_centavos')::bigint;end if;return new;
end;$$;
-- PostgreSQL orders BEFORE triggers by name: run after tariff/contract snapshots.
create trigger zzz_empresa_quote before insert on public.diarias for each row execute function direct_private.empresa_quote_snapshot();

create function direct_private.empresa_finance_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare r public.empresa_registros;begin
 if old.empresa_registro_id is null then return case when tg_op='DELETE' then old else new end;end if;
 if tg_op='DELETE' then raise exception 'Preserve a despesa aprovada e seu lançamento.';end if;
 if new.empresa_registro_id is distinct from old.empresa_registro_id or new.tipo<>old.tipo or new.valor_centavos<>old.valor_centavos or new.vencimento<>old.vencimento or new.categoria<>old.categoria or new.contraparte<>old.contraparte or new.descricao<>old.descricao then raise exception 'Os dados da despesa aprovada estão preservados.';end if;
 if exists(select 1 from public.empresa_extrato where destino_tipo='lancamento' and destino_id=old.id and estado='conciliado') and (new.data_pagamento is distinct from old.data_pagamento or new.forma_pagamento<>old.forma_pagamento) then raise exception 'Pagamento já conciliado. Preserve a conferência do extrato.';end if;
 return new;
end;$$;
create trigger empresa_finance_guard before update or delete on public.financeiro_lancamentos for each row execute function direct_private.empresa_finance_guard();
create function direct_private.empresa_finance_sync() returns trigger language plpgsql security definer set search_path='' as $$
begin if new.empresa_registro_id is not null then
 update public.empresa_registros set status=case when new.data_pagamento is null then 'aprovada' else 'paga' end,
 dados=case when new.data_pagamento is null then dados-'data_pagamento'-'forma' else dados||jsonb_build_object('data_pagamento',new.data_pagamento,'forma',new.forma_pagamento) end,
 versao=versao+1,atualizado_em=clock_timestamp() where id=new.empresa_registro_id and (status is distinct from case when new.data_pagamento is null then 'aprovada' else 'paga' end or dados->>'data_pagamento' is distinct from new.data_pagamento::text or coalesce(dados->>'forma','')<>new.forma_pagamento);
 end if;return new;end;$$;
create trigger empresa_finance_sync after insert or update on public.financeiro_lancamentos for each row execute function direct_private.empresa_finance_sync();

create function public.direct_empresa_compartilhar_relatorio(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();r public.empresa_registros;code text;
begin
 if member not in ('admin','operacao') then raise exception 'Seu perfil não pode compartilhar relatórios.' using errcode='42501';end if;
 r:=direct_private.empresa_get((p->>'id')::bigint,'relatorio');if r.status<>'aprovado' or r.versao<>(p->>'versao')::bigint then raise exception 'Escolha um relatório aprovado e atualizado.';end if;
 insert into direct_private.empresa_compartilhamentos(registro_id) values(r.id) on conflict(registro_id) do nothing;
 select codigo into code from direct_private.empresa_compartilhamentos where registro_id=r.id;return jsonb_build_object('codigo',code);
end;$$;
create function public.direct_empresa_relatorio_publico(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare r public.empresa_registros;code text:=p->>'codigo';begin
 if coalesce(code,'') !~ '^[A-Za-z0-9_-]{24}$' then raise exception 'Link de relatório inválido.' using errcode='42501';end if;
 select rec.* into r from direct_private.empresa_compartilhamentos c join public.empresa_registros rec on rec.id=c.registro_id where c.codigo=code and rec.status='aprovado';
 if r.id is null then raise exception 'Relatório não disponível.' using errcode='42501';end if;
 return jsonb_build_object('titulo',r.titulo,'inicio',r.dados->>'inicio','fim',r.dados->>'fim','resumo',r.dados->>'resumo','resultado',r.dados->>'resultado','versao',r.versao,'aprovado_em',r.atualizado_em);
end;$$;

create function public.direct_empresa_extrato(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();account bigint:=(p->>'conta_id')::bigint;page int:=greatest(1,coalesce((p->>'pagina')::int,1));begin
 if member not in ('admin','financeiro') then raise exception 'Somente Financeiro/Admin consulta extratos.' using errcode='42501';end if;perform direct_private.empresa_get(account,'conta');
 return jsonb_build_object('items',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select * from public.empresa_extrato where conta_id=account order by data desc,id desc limit 50 offset (page-1)*50)x),'total',(select count(*) from public.empresa_extrato where conta_id=account),'pagina',page);
end;$$;
create function public.direct_empresa_importar_extrato(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();account public.empresa_registros;r jsonb;line public.empresa_extrato;token text;canonical text;seen jsonb:='{}';occurrence int;amount bigint;day date;description text;identifier text;key text;inserted int:=0;skipped int:=0;
begin
 if member not in ('admin','financeiro') then raise exception 'Somente Financeiro/Admin importa extratos.' using errcode='42501';end if;
 account:=direct_private.empresa_get((p->>'conta_id')::bigint,'conta');if account.status<>'ativo' or jsonb_typeof(p->'linhas')<>'array' or jsonb_array_length(p->'linhas') not between 1 and 500 then raise exception 'Escolha uma conta ativa e importe até 500 linhas.';end if;
 perform 1 from public.empresa_registros where id=account.id for update;
 for r in select * from jsonb_array_elements(p->'linhas') loop
  if jsonb_typeof(r)<>'object' or jsonb_typeof(r->'valor_centavos')<>'number' or (r->>'valor_centavos') !~ '^-?[0-9]+$' or (r->>'data') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Linha de extrato inválida.';end if;
  day:=(r->>'data')::date;amount:=(r->>'valor_centavos')::bigint;description:=trim(coalesce(r->>'descricao',''));identifier:=coalesce(r->>'identificador','');
  if amount=0 or abs(amount)>1000000000 or length(description)>500 or length(identifier)>180 then raise exception 'Confira valor e textos do extrato.';end if;
  canonical:=jsonb_build_array(day,amount,description)::text;occurrence:=coalesce((seen->>canonical)::int,0)+1;seen:=seen||jsonb_build_object(canonical,occurrence);token:=case when identifier<>'' then identifier else canonical||'#'||occurrence end;key:=md5(account.id||':'||token);
  select * into line from public.empresa_extrato where chave=key;
  if line.id is not null then if line.data<>day or line.valor_centavos<>amount or line.descricao<>description then raise exception 'Identificador bancário já utilizado com outros dados.';end if;skipped:=skipped+1;
  else insert into public.empresa_extrato(conta_id,chave,data,valor_centavos,descricao,identificador) values(account.id,key,day,amount,description,identifier);inserted:=inserted+1;end if;
 end loop;return jsonb_build_object('importadas',inserted,'repetidas',skipped);
end;$$;
create function public.direct_empresa_conciliar(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();line public.empresa_extrato;target text:=p->>'destino_tipo';rid bigint:=nullif(p->>'destino_id','')::bigint;entry public.financeiro_lancamentos;batch public.pagamento_lotes;
begin
 if member not in ('admin','financeiro') then raise exception 'Somente Financeiro/Admin confere o extrato.' using errcode='42501';end if;
 select * into line from public.empresa_extrato where id=(p->>'id')::bigint for update;
 if line.id is null or line.versao<>coalesce((p->>'versao')::bigint,0) or line.estado<>'pendente' then raise exception 'Linha já conferida ou alterada. Atualize o extrato.';end if;
 if target='ignorar' then if length(coalesce(p->>'motivo',''))<8 then raise exception 'Explique por que a linha não será vinculada.';end if;
 elsif target='cobranca' then if line.valor_centavos<=0 then raise exception 'Escolha uma entrada para recebimento.';end if;perform direct_private.direct_receive_invoice(rid,line.valor_centavos,line.data,'Extrato conferido');
 elsif target='lancamento' then
  select * into entry from public.financeiro_lancamentos where id=rid for update;
  if entry.id is null or entry.valor_centavos<>abs(line.valor_centavos) or (entry.tipo='receita')<>(line.valor_centavos>0) or (entry.data_pagamento is not null and entry.data_pagamento<>line.data) then raise exception 'Confira valor, sentido e data do lançamento.';end if;
  if exists(select 1 from public.empresa_extrato where destino_tipo=target and destino_id=rid and estado='conciliado') then raise exception 'Lançamento já conciliado.';end if;
  update public.financeiro_lancamentos set data_pagamento=line.data,forma_pagamento=case when data_pagamento is null then 'Extrato conferido' else forma_pagamento end,atualizado_em=clock_timestamp() where id=rid;
 elsif target='lote_pagamento' then
  select * into batch from public.pagamento_lotes where id=rid for update;
  if batch.id is null or batch.status<>'pago' or line.valor_centavos>=0 or batch.valor_centavos<>-line.valor_centavos or batch.data_pagamento<>line.data then raise exception 'Escolha o lote pago com o mesmo valor e data.';end if;
  if exists(select 1 from public.empresa_extrato where destino_tipo=target and destino_id=rid and estado='conciliado') then raise exception 'Lote já conciliado.';end if;
 else raise exception 'Vínculo inválido.';end if;
 update public.empresa_extrato set estado=case when target='ignorar' then 'ignorada' else 'conciliado' end,destino_tipo=target,destino_id=case when target='ignorar' then null else rid end,motivo=coalesce(p->>'motivo',''),versao=versao+1,atualizado_em=clock_timestamp() where id=line.id returning * into line;return to_jsonb(line);
end;$$;

create function public.direct_empresa_anexos(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$begin perform direct_private.empresa_role();perform direct_private.empresa_get((p->>'registro_id')::bigint);return (select coalesce(jsonb_agg(to_jsonb(a)),'[]') from public.empresa_anexos a where registro_id=(p->>'registro_id')::bigint);end;$$;
create function public.direct_empresa_anexo(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();r public.empresa_registros;result public.empresa_anexos;path text:=p->>'caminho';size bigint;
begin
 r:=direct_private.empresa_get((p->>'registro_id')::bigint);if not(direct_private.empresa_contract()->'entities'->r.tipo->'write' ? member) or r.tipo in ('acesso','conta','frase','leitura_aviso') then raise exception 'Seu perfil não pode anexar esta evidência.' using errcode='42501';end if;
 if path !~ ('^'||r.id||'/[a-f0-9]{64}$') or (p->>'sha256') !~ '^[a-f0-9]{64}$' or path<>r.id||'/'||(p->>'sha256') or length(coalesce(p->>'nome','')) not between 1 and 120 or p->>'mime' not in ('image/jpeg','image/png','image/webp') then raise exception 'Anexo inválido.';end if;
 perform 1 from public.empresa_registros where id=r.id for update;
 select (metadata->>'size')::bigint into size from storage.objects where bucket_id='direct-evidencias' and name=path and owner_id=auth.uid()::text;
 if size is null or size not between 1 and 1048576 or size<>(p->>'bytes')::bigint then raise exception 'Faça o envio da imagem antes de registrar o anexo.';end if;
 select * into result from public.empresa_anexos where caminho=path;if result.id is not null then return to_jsonb(result);end if;
 if (select count(*) from public.empresa_anexos where registro_id=r.id)>=8 then raise exception 'Use até 8 fotos por registro.';end if;
 insert into public.empresa_anexos(registro_id,nome,mime,bytes,caminho,sha256,autor) values(r.id,p->>'nome',p->>'mime',size,path,p->>'sha256',auth.jwt()->>'email') returning * into result;return to_jsonb(result);
end;$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('direct-evidencias','direct-evidencias',false,1048576,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy empresa_storage_read on storage.objects for select to authenticated using(bucket_id='direct-evidencias' and exists(select 1 from public.empresa_registros r where r.id::text=(storage.foldername(name))[1]));
create policy empresa_storage_insert on storage.objects for insert to authenticated with check(bucket_id='direct-evidencias' and owner_id=(select auth.uid())::text and exists(select 1 from public.empresa_registros r where r.id::text=(storage.foldername(name))[1] and (direct_private.empresa_contract()->'entities'->r.tipo->'write' ? (select direct_private.member_role()))));
-- Unregistered uploads can be removed by their owner after a failed metadata save.
create policy empresa_storage_cleanup on storage.objects for delete to authenticated using(bucket_id='direct-evidencias' and owner_id=(select auth.uid())::text and not exists(select 1 from public.empresa_anexos where caminho=name));

create function public.direct_empresa_historico(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$begin perform direct_private.empresa_role();return (select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select * from public.empresa_registros r where r.cliente_id=(p->>'cliente_id')::bigint and tipo in ('contato','oportunidade','relatorio','campanha','feedback','vinculo','tarefa','proposta') and direct_private.empresa_visible(r) order by id desc limit 100)x);end;$$;
create function public.direct_empresa_alertas(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare day date:=coalesce(nullif(p->>'data','')::date,(now() at time zone 'America/Fortaleza')::date);begin perform direct_private.empresa_role();return (select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(
 select id,tipo,titulo,case when tipo='tarefa' then 'Prazo vencido ou vence hoje' when tipo='contato' then 'Retorno agendado' else 'Vencido ou próximo da validade' end motivo,coalesce(dados->>'supervisor',dados->>'responsavel',dados->>'conferido_por','') responsavel from public.empresa_registros r where direct_private.empresa_visible(r) and ((tipo='tarefa' and status not in ('concluida','cancelada') and (dados->>'prazo')::timestamptz::date<=day) or (tipo='contato' and (dados->>'retorno')::date<=day) or (tipo in ('qualificacao','lote') and status not in ('revogada','arquivado') and (dados->>'validade')::date<=day+coalesce((dados->>'antecedencia_dias')::int,0))) order by id desc limit 100)x);end;$$;

create function public.direct_empresa_painel(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();start_day date:=coalesce(nullif(p->>'inicio','')::date,date_trunc('month',now() at time zone 'America/Fortaleza')::date);end_day date:=coalesce(nullif(p->>'fim','')::date,(now() at time zone 'America/Fortaleza')::date);today date:=(now() at time zone 'America/Fortaleza')::date;orders bigint[];result jsonb;revenue bigint;cost bigint;expenses bigint;missing bigint;expected bigint;planned bigint;estimated bigint;
begin
 if start_day>end_day or end_day-start_day>366 then raise exception 'Escolha um período de até 366 dias.';end if;
 select coalesce(array_agg(o.id),'{}') into orders from public.pedidos o where o.situacao<>'cancelado' and (coalesce(p->>'rede','')='' or o.supermercado=p->>'rede') and (coalesce(p->>'loja','')='' or o.unidade=p->>'loja') and (coalesce(p->>'setor','')='' or o.setor=p->>'setor') and
 (coalesce(p->>'campanha_id','')='' or exists(select 1 from public.empresa_registros v where v.tipo='vinculo' and v.pedido_id=o.id and v.campanha_id=(p->>'campanha_id')::bigint and direct_private.empresa_visible(v))) and
 (coalesce(p->>'cliente_id','')='' or exists(select 1 from public.empresa_registros v where v.tipo='vinculo' and v.pedido_id=o.id and v.cliente_id=(p->>'cliente_id')::bigint and direct_private.empresa_visible(v))) and
 (direct_private.empresa_scope(null) or exists(select 1 from public.empresa_registros v where v.tipo='vinculo' and v.pedido_id=o.id and direct_private.empresa_visible(v)));
 select jsonb_build_object('inicio',start_day,'fim',end_day,'gerado_em',clock_timestamp(),
 'demanda',coalesce((select sum(o.quantidade_diaristas) from public.pedidos o cross join lateral jsonb_array_elements(o.turnos) t where o.id=any(orders) and (t->>'data')::date between start_day and end_day),0),
 'preenchidas',count(*) filter(where s.status not in ('falta','desistiu')),'presencas',count(*) filter(where s.status='presente'),'faltas',count(*) filter(where s.status='falta'),
 'presencas_pendentes',count(*) filter(where s.status='escalada' and s.data<=today),'registros_considerados',count(*),
 'fontes',jsonb_build_array('Pedidos','Escalas e presenças','Diárias vinculadas'),
 'pedidos',(select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'titulo','#'||o.id||' · '||o.supermercado||' · '||o.unidade)),'[]') from public.pedidos o where o.id=any(orders) and exists(select 1 from jsonb_array_elements(o.turnos)t where (t->>'data')::date between start_day and end_day))) into result from public.pedido_escalas s where s.pedido_id=any(orders) and s.data between start_day and end_day;
 result:=result||jsonb_build_object('execucao',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(
  select o.supermercado rede,(t->>'data')::date data,sum(o.quantidade_diaristas) demanda,
  sum((select count(*) from public.pedido_escalas s where s.pedido_id=o.id and s.data=(t->>'data')::date and s.status not in ('falta','desistiu'))) preenchidas,
  sum((select count(*) from public.pedido_escalas s where s.pedido_id=o.id and s.data=(t->>'data')::date and s.status='presente')) presencas,
  sum((select count(*) from public.pedido_escalas s where s.pedido_id=o.id and s.data=(t->>'data')::date and s.confirmacao='confirmada')) confirmadas,
  bool_or(exists(select 1 from public.empresa_registros c where c.tipo='fechamento' and c.status='fechado' and c.dados->>'data'=t->>'data' and c.pedido_id is null and c.campanha_id is not distinct from nullif(p->>'campanha_id','')::bigint and c.cliente_id is not distinct from nullif(p->>'cliente_id','')::bigint)) fechado
  from public.pedidos o cross join lateral jsonb_array_elements(o.turnos)t where o.id=any(orders) and (t->>'data')::date between start_day and end_day group by o.supermercado,t->>'data' order by data,rede limit 200)x));
 if member in ('admin','financeiro') then
  select coalesce(sum(d.valor_recebido_centavos),0),coalesce(sum(d.valor_centavos),0),count(*) filter(where d.valor_centavos is null or d.valor_recebido_centavos is null) into revenue,cost,missing from public.diarias d join public.pedido_escalas s on s.id=d.pedido_escala_id where s.pedido_id=any(orders) and d.data between start_day and end_day;
  select coalesce(sum((r.dados->>'valor_centavos')::bigint),0) into expenses from public.empresa_registros r where tipo='despesa' and status in ('aprovada','paga') and (r.dados->>'data')::date between start_day and end_day and direct_private.empresa_visible(r) and (coalesce(p->>'cliente_id','')='' or cliente_id=(p->>'cliente_id')::bigint) and (coalesce(p->>'campanha_id','')='' or campanha_id=(p->>'campanha_id')::bigint) and ((coalesce(p->>'rede','')='' and coalesce(p->>'loja','')='' and coalesce(p->>'setor','')='') or pedido_id=any(orders)) and lower(coalesce((select c.dados->>'centro_custo' from public.empresa_registros c where c.id=(r.dados->>'categoria_id')::bigint),'')) not in ('administração','administracao');
  select coalesce(sum(o.quantidade_diaristas*(q.dados->>'custo_unitario_centavos')::bigint),0) into expected from public.empresa_registros q join public.pedidos o on o.id=q.pedido_id cross join lateral jsonb_array_elements(o.turnos)t where q.tipo='proposta' and q.status='convertida' and o.id=any(orders) and (t->>'data')::date between start_day and end_day;
  select coalesce(sum((q.dados->>'custo_unitario_centavos')::bigint),0) into planned from public.pedido_escalas s join public.empresa_registros q on q.pedido_id=s.pedido_id and q.tipo='proposta' and q.status='convertida' where s.pedido_id=any(orders) and s.status not in ('falta','desistiu') and s.data between start_day and end_day;
  select coalesce(sum((r.dados->>'orcamento_custo_centavos')::bigint),0) into estimated from public.empresa_registros r where tipo='orcamento' and status='aprovado' and direct_private.empresa_visible(r) and exists(select 1 from public.empresa_registros c where c.id=r.campanha_id and (c.dados->>'inicio')::date<=end_day and (c.dados->>'fim')::date>=start_day) and (coalesce(p->>'campanha_id','')='' or r.campanha_id=(p->>'campanha_id')::bigint) and (coalesce(p->>'cliente_id','')='' or r.cliente_id=(p->>'cliente_id')::bigint);
  result:=result||jsonb_build_object('aportes_centavos',(select coalesce(sum((c.dados->>'valor_centavos')::bigint),0) from public.empresa_registros c where c.tipo='movimento_caixa' and c.dados->>'tipo'='aporte' and (c.dados->>'data')::date between start_day and end_day),'retiradas_centavos',(select coalesce(sum((c.dados->>'valor_centavos')::bigint),0) from public.empresa_registros c where c.tipo='movimento_caixa' and c.dados->>'tipo'='retirada' and (c.dados->>'data')::date between start_day and end_day),'receita_real_centavos',revenue,'diarias_custo_centavos',cost,'despesas_aprovadas_centavos',expenses,'margem_contribuicao_centavos',revenue-cost-expenses,'valores_incompletos',missing,'custo_estimado_campanhas_centavos',estimated,'custo_contratado_propostas_centavos',expected,'custo_planejado_propostas_centavos',planned,
  'saldo_atrasado_centavos',(select coalesce(sum(c.valor_centavos-coalesce((select sum(r.valor_centavos) from public.cobranca_recebimentos r where r.cobranca_id=c.id and not r.estornado),0)),0) from public.cobrancas c where c.status='aberta' and c.vencimento<today and exists(select 1 from public.cobranca_itens i where i.cobranca_id=c.id and i.pedido_id=any(orders))),
  'cobrancas_atrasadas',(select count(*) from public.cobrancas c where c.status='aberta' and c.vencimento<today and exists(select 1 from public.cobranca_itens i where i.cobranca_id=c.id and i.pedido_id=any(orders))));
 end if;return result;
end;$$;
create function public.direct_empresa_cobrancas(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();begin if member not in ('admin','financeiro') then raise exception 'Seu perfil não pode consultar cobranças.' using errcode='42501';end if;
 return (select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select c.*,coalesce((select sum(r.valor_centavos) from public.cobranca_recebimentos r where r.cobranca_id=c.id and not r.estornado),0) valor_recebido_centavos from public.cobrancas c where c.status='aberta' and (direct_private.empresa_scope(null) or exists(select 1 from public.cobranca_itens i join public.empresa_registros v on v.pedido_id=i.pedido_id where i.cobranca_id=c.id and v.tipo='vinculo' and direct_private.empresa_visible(v))) and (coalesce(p->>'cliente_id','')='' and coalesce(p->>'campanha_id','')='' or exists(select 1 from public.cobranca_itens i join public.empresa_registros v on v.pedido_id=i.pedido_id where i.cobranca_id=c.id and v.tipo='vinculo' and (coalesce(p->>'cliente_id','')='' or v.cliente_id=(p->>'cliente_id')::bigint) and (coalesce(p->>'campanha_id','')='' or v.campanha_id=(p->>'campanha_id')::bigint))) order by c.vencimento limit 500)x);
end;$$;
create function public.direct_empresa_reservas(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();o public.pedidos;today date:=(now() at time zone 'America/Fortaleza')::date;
begin if member not in ('admin','operacao') then raise exception 'Seu perfil não pode selecionar equipe.' using errcode='42501';end if;
 select * into o from public.pedidos where id=(p->>'pedido_id')::bigint;
 if o.id is null or (not direct_private.empresa_scope(null) and not exists(select 1 from public.empresa_registros v where v.pedido_id=o.id and v.tipo='vinculo' and direct_private.empresa_visible(v))) then raise exception 'Pedido fora do escopo.' using errcode='42501';end if;
 return jsonb_build_object('pedido_id',o.id,'datas',(select jsonb_agg(t->>'data') from jsonb_array_elements(o.turnos)t),'items',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(
 select w.id,w.nome,true elegivel,jsonb_build_array(case when exists(select 1 from jsonb_array_elements_text(w.setores)s where lower(s)=lower(o.setor)) then 'Experiência declarada na função' else 'Função não consta na experiência declarada' end)||coalesce((select jsonb_agg('Conferido: '||r.titulo) from public.empresa_registros r where r.tipo='qualificacao' and r.diarista_id=w.id and r.status='conferida' and ((r.dados->>'validade')::date is null or (r.dados->>'validade')::date>=greatest(today,(select max((t->>'data')::date) from jsonb_array_elements(o.turnos)t)))),'[]') motivos,
 jsonb_build_array('Confirmar interesse e disponibilidade para este pedido antes de escalar.') avisos
 from public.diaristas w where not w.bloqueada order by exists(select 1 from jsonb_array_elements_text(w.setores)s where lower(s)=lower(o.setor)) desc,w.nome limit 100)x));
end;$$;

-- Every new API denies public/anonymous execution unless explicitly external.
do $$declare f record;begin for f in select n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='direct_private' and p.proname like 'empresa_%') or (n.nspname='public' and p.proname like 'direct_empresa_%') loop
 execute format('revoke all on function %I.%I(%s) from public,anon,authenticated',f.nspname,f.proname,f.args);
 if f.nspname='public' then execute format('grant execute on function %I.%I(%s) to authenticated',f.nspname,f.proname,f.args);end if;
end loop;end;$$;
grant execute on function public.direct_empresa_relatorio_publico(jsonb) to anon;
-- Helpers called by RLS policies need execution, and still use trusted membership.
grant execute on function direct_private.empresa_contract(),direct_private.empresa_visible(public.empresa_registros),direct_private.empresa_scope(bigint) to authenticated;

insert into public.empresa_registros(tipo,titulo,status,dados,chave,autor)
 select 'categoria',name,'ativo',jsonb_build_object('tipo','despesa','centro_custo',case when name='Administração' then 'Administração' else 'Serviços' end),'seed:categoria:'||name,'Sistema' from unnest(array['Transporte','Alimentação','Materiais','Administração'])name;
insert into public.empresa_registros(tipo,titulo,status,dados,chave,autor)
 select 'rede',min(rede),'ativo',jsonb_build_object('tipo','supermercado'),'seed:rede:'||min(rede),'Sistema' from public.lojas group by lower(trim(rede));

-- Dynamic networks preserve all validation and names already bound to private links.
alter table public.lojas drop constraint direct_lojas_valid_fields;
alter table public.lojas add constraint direct_lojas_valid_fields check (
 length(btrim(rede)) between 1 and 180 and length(btrim(nome)) between 1 and 120
 and length(btrim(endereco)) between 1 and 250 and length(bairro)<=100
 and length(btrim(cidade)) between 1 and 80 and uf='CE' and length(observacao)<=400
 and length(fonte_url)<=500 and (fonte_url='' or fonte_url ~ '^https://[^[:space:]]+$'));
create function direct_private.empresa_network_guard() returns trigger language plpgsql security definer set search_path='' as $$begin
 if tg_table_name='lojas' then
  if tg_op='UPDATE' and new.rede=old.rede then return new;end if;
  if new.rede not in ('Super do Povo','Super Lagoa','Fazendinha','Hipermarket','Pinheiro','Variedades') and not exists(select 1 from public.empresa_registros where tipo='rede' and status='ativo' and titulo=new.rede) and not exists(select 1 from public.lojas where rede=new.rede) then raise exception 'Cadastre primeiro a rede na área Empresa.';end if;
 else
  if tg_op='UPDATE' and old.tipo='rede' and new.titulo<>old.titulo and exists(select 1 from public.lojas where rede=old.titulo) then raise exception 'Preserve o nome da rede vinculada às lojas e links existentes.';end if;
 end if;return new;end;$$;
create trigger empresa_network_guard before insert or update on public.lojas for each row execute function direct_private.empresa_network_guard();
create trigger empresa_network_catalog before insert or update on public.empresa_registros for each row execute function direct_private.empresa_network_guard();
create function public.direct_empresa_diarias_pendentes(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();begin
 if member not in ('admin','financeiro') then raise exception 'Somente Financeiro/Admin confere pagamentos.' using errcode='42501';end if;
 return(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select d.id,d.data,d.local,d.setor,d.valor_centavos,d.diarista_id,w.nome from public.diarias d join public.diaristas w on w.id=d.diarista_id where d.data_pagamento is null and d.pagamento_lote_id is null and d.valor_centavos>0 and (nullif(p->>'diarista_id','') is null or d.diarista_id=(p->>'diarista_id')::bigint) order by d.data,d.id limit 500)x);end;$$;
create function public.direct_empresa_registrar_pagamento(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();r public.empresa_registros;snapshot jsonb;ids bigint[];bid bigint;day date;method text:=trim(coalesce(p->>'forma',''));begin
 if member not in ('admin','financeiro') then raise exception 'Somente Financeiro/Admin registra pagamentos.' using errcode='42501';end if;
 r:=direct_private.empresa_get((p->>'id')::bigint,'pagamento_revisao');select * into r from public.empresa_registros where id=r.id for update;
 if r.status='registrado' then return jsonb_build_object('lote_id',r.dados->'lote_id','repetido',true);end if;
 if r.status<>'aprovado' or r.versao<>coalesce((p->>'versao')::bigint,0) then raise exception 'Escolha uma conferência aprovada e atualizada.';end if;
 if coalesce(p->>'data_pagamento','') !~ '^\d{4}-\d{2}-\d{2}$' or length(method) not between 1 and 80 then raise exception 'Confira a data e a forma de pagamento.';end if;day:=(p->>'data_pagamento')::date;
 select array_agg(value::text::bigint) into ids from jsonb_array_elements(r.dados->'diaria_ids');perform 1 from public.diarias where id=any(ids) for update;
 select jsonb_agg(jsonb_build_object('id',id,'diarista_id',diarista_id,'valor_centavos',valor_centavos,'data_pagamento',data_pagamento) order by id) into snapshot from public.diarias where id=any(ids);
 if snapshot is distinct from r.dados->'diarias_snapshot' then raise exception 'As diárias mudaram; prepare uma nova conferência.';end if;
 bid:=direct_private.direct_pay_daily_batch(r.diarista_id,ids,day,method);
 update public.empresa_registros set status='registrado',dados=dados||jsonb_build_object('lote_id',bid,'data_registro',day,'forma_registro',method),versao=versao+1,atualizado_em=clock_timestamp() where id=r.id;
 return jsonb_build_object('lote_id',bid,'valor_centavos',r.dados->'valor_conferido_centavos');end;$$;
revoke all on function direct_private.empresa_network_guard(),public.direct_empresa_diarias_pendentes(jsonb),public.direct_empresa_registrar_pagamento(jsonb) from public,anon,authenticated;
grant execute on function public.direct_empresa_diarias_pendentes(jsonb),public.direct_empresa_registrar_pagamento(jsonb) to authenticated;

create function public.direct_empresa_configurar_rede(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();r public.empresa_registros;income bigint;cost bigint;begin
 if member not in ('admin','financeiro') then raise exception 'Somente Financeiro/Admin configura valores.' using errcode='42501';end if;r:=direct_private.empresa_get((p->>'rede_id')::bigint,'rede');
 if jsonb_typeof(p->'valor_recebido_centavos')<>'number' or jsonb_typeof(p->'valor_padrao_centavos')<>'number' or p->>'valor_recebido_centavos' !~ '^[0-9]+$' or p->>'valor_padrao_centavos' !~ '^[0-9]+$' then raise exception 'Informe valores em centavos.';end if;
 income:=(p->>'valor_recebido_centavos')::bigint;cost:=(p->>'valor_padrao_centavos')::bigint;if income not between 1 and 1000000000 or cost not between 1 and 1000000000 then raise exception 'Informe valores válidos maiores que zero.';end if;
 insert into public.tarifas_redes(rede,valor_recebido_centavos,valor_padrao_centavos) values(r.titulo,income,cost) on conflict(rede) do update set valor_recebido_centavos=excluded.valor_recebido_centavos,valor_padrao_centavos=excluded.valor_padrao_centavos,atualizado_em=clock_timestamp();return jsonb_build_object('ok',true);end;$$;
revoke all on function public.direct_empresa_configurar_rede(jsonb) from public,anon,authenticated;grant execute on function public.direct_empresa_configurar_rede(jsonb) to authenticated;
create function public.direct_empresa_candidatos_extrato(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();line public.empresa_extrato;begin
 if member not in ('admin','financeiro') then raise exception 'Somente Financeiro/Admin confere extratos.' using errcode='42501';end if;
 select * into line from public.empresa_extrato where id=(p->>'id')::bigint;if line.id is null then raise exception 'Linha não encontrada.';end if;
 return jsonb_build_object('lancamento',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select f.id,f.descricao titulo from public.financeiro_lancamentos f where f.valor_centavos=abs(line.valor_centavos) and (f.tipo='receita')=(line.valor_centavos>0) and (f.data_pagamento is null or f.data_pagamento=line.data) and not exists(select 1 from public.empresa_extrato e where e.destino_tipo='lancamento' and e.destino_id=f.id and e.estado='conciliado') order by f.id limit 100)x),
 'cobranca',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select c.id,c.rede||' · '||c.periodo_inicio||' a '||c.periodo_fim titulo from public.cobrancas c where line.valor_centavos>0 and c.status='aberta' and c.valor_centavos-coalesce((select sum(r.valor_centavos) from public.cobranca_recebimentos r where r.cobranca_id=c.id and not r.estornado),0)>=line.valor_centavos order by c.vencimento limit 100)x),
 'lote_pagamento',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from(select b.id,w.nome||' · '||b.quantidade||' diária(s)' titulo from public.pagamento_lotes b join public.diaristas w on w.id=b.diarista_id where line.valor_centavos<0 and b.status='pago' and b.valor_centavos=-line.valor_centavos and b.data_pagamento=line.data and not exists(select 1 from public.empresa_extrato e where e.destino_tipo='lote_pagamento' and e.destino_id=b.id and e.estado='conciliado') order by b.id limit 100)x));end;$$;
revoke all on function public.direct_empresa_candidatos_extrato(jsonb) from public,anon,authenticated;grant execute on function public.direct_empresa_candidatos_extrato(jsonb) to authenticated;
create or replace function public.direct_empresa_alertas(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare member text:=direct_private.empresa_role();today date:=coalesce(nullif(p->>'data','')::date,(now() at time zone 'America/Fortaleza')::date);result jsonb;begin
 with records as(select r.*,case r.tipo when 'tarefa' then (r.dados->>'prazo')::timestamptz::date when 'contato' then (r.dados->>'retorno')::date else (r.dados->>'validade')::date end deadline,case r.tipo when 'tarefa' then 'tarefa_vencida' when 'qualificacao' then 'qualificacao_vencida' when 'lote' then 'lote_vencido' end rulekind from public.empresa_registros r where r.tipo in ('tarefa','qualificacao','lote','contato') and r.status not in ('concluida','cancelada','revogada','arquivado') and direct_private.empresa_visible(r)),alerts as(
 select r.id,r.tipo,r.titulo,case when r.deadline<today then 'Prazo vencido' else 'Prazo próximo ou vence hoje' end||coalesce((select ' · '||string_agg(q.dados->>'acao',' · ') from public.empresa_registros q where q.tipo='regra' and q.status='ativo' and q.dados->>'tipo'=r.rulekind),'') motivo,concat_ws(', ',coalesce(r.dados->>'supervisor',r.dados->>'responsavel',r.dados->>'conferido_por'),(select string_agg(q.dados->>'responsavel',', ') from public.empresa_registros q where q.tipo='regra' and q.status='ativo' and q.dados->>'tipo'=r.rulekind)) responsavel from records r where deadline<=today+greatest(coalesce((r.dados->>'antecedencia_dias')::int,0),coalesce((select max((q.dados->>'antecedencia_dias')::int) from public.empresa_registros q where q.tipo='regra' and q.status='ativo' and q.dados->>'tipo'=r.rulekind),0))
 union all select c.id,'cobranca','Cobrança · '||c.rede,q.dados->>'acao',q.dados->>'responsavel' from public.cobrancas c join public.empresa_registros q on q.tipo='regra' and q.status='ativo' and q.dados->>'tipo'='cobranca_atrasada' where member in ('admin','financeiro') and c.status='aberta' and c.vencimento<=today+(q.dados->>'antecedencia_dias')::int and c.valor_centavos>coalesce((select sum(x.valor_centavos) from public.cobranca_recebimentos x where x.cobranca_id=c.id and not x.estornado),0) and (direct_private.empresa_scope(null) or exists(select 1 from public.cobranca_itens i join public.empresa_registros v on v.pedido_id=i.pedido_id and v.tipo='vinculo' where i.cobranca_id=c.id and direct_private.empresa_visible(v)))) select coalesce(jsonb_agg(to_jsonb(x)),'[]') into result from(select * from alerts order by titulo limit 100)x;return result;end;$$;
revoke all on function public.direct_empresa_alertas(jsonb) from public,anon,authenticated;grant execute on function public.direct_empresa_alertas(jsonb) to authenticated;

create function direct_private.backup_snapshot_v10() returns jsonb language sql stable security invoker set search_path='' as $$
with data as(select direct_private.backup_snapshot_v9()->'tables'||jsonb_build_object(
 'empresa_registros',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.empresa_registros t),
 'empresa_extrato',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.empresa_extrato t),
 'empresa_anexos',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.empresa_anexos t),
 'empresa_compartilhamentos',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from direct_private.empresa_compartilhamentos t)) tables)
select jsonb_build_object('format','direct-data-v10','exportedAt',now(),'tables',tables,'snapshot',jsonb_build_object('consistent',true,'counts',(select jsonb_object_agg(key,jsonb_array_length(value)) from jsonb_each(data.tables)))) from data;$$;
revoke all on function direct_private.backup_snapshot_v10() from public,anon,authenticated;
create function public.direct_backup_snapshot_v10() returns jsonb language plpgsql stable security definer set search_path='' as $$begin if auth.uid() is null or coalesce(direct_private.member_role(),'')<>'admin' then raise exception 'Somente administrador.' using errcode='42501';end if;return direct_private.backup_snapshot_v10();end;$$;
revoke all on function public.direct_backup_snapshot_v10() from public,anon,authenticated;grant execute on function public.direct_backup_snapshot_v10() to authenticated;
do $$declare ddl text;begin select pg_get_functiondef('public.direct_backup_bundle(text,uuid)'::regprocedure) into ddl;execute replace(ddl,'direct_private.backup_snapshot_v9()','direct_private.backup_snapshot_v10()');end;$$;
create function public.direct_backup_attachment_manifest(p_token text,p_run uuid,p_ids bigint[]) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare agent uuid:=direct_private.backup_agent(p_token);begin
 if not exists(select 1 from direct_private.backup_runs where id=p_run and agent_id=agent and state='running' and started_at>now()-interval '30 minutes') or cardinality(p_ids) not between 1 and 100 then raise exception 'Sessão de backup inválida.' using errcode='42501';end if;
 return(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'caminho',a.caminho,'sha256',a.sha256,'bytes',a.bytes)),'[]') from public.empresa_anexos a where a.id=any(p_ids));end;$$;
revoke all on function public.direct_backup_attachment_manifest(text,uuid,bigint[]) from public,anon,authenticated;grant execute on function public.direct_backup_attachment_manifest(text,uuid,bigint[]) to anon,authenticated;
